			public ProfitShareRulesGridAttacher(IBusinessObjectCollection destinationCollection, IBusinessObjectCollection findBoxList, ModuleIdentifier moduleID)
				: base(destinationCollection, findBoxList, moduleID) { }

			protected override bool AttachCore(BusinessObject bizO, List<BusinessObject> listToBulkAdd)
			{
				var loaded = bizO.Factory.Load<OrgAgentRelationship>(bizO.PK);
				if (loaded == null || loaded.IsDeleted)
				{
					return false;
				}

				if (((IFindBox)this).PopupForm is EmbeddedModulePopup popup
					&& popup.Controls.Find("ProfitShareGrid", true).FirstOrDefault() is ZGrid profitShareGrid)
				{
					// Store the selected rules from ProfitShareGrid in the bizO so that we show only these items.
					loaded.SelectedProfitShareDetailsList.AddRange(profitShareGrid.SelectedElements.OfType<OrgProfitShareDetails>());
				}
				listToBulkAdd.Add(loaded);
				return true;
			}

			/// <summary>
